    45→
    46→/**
    47→ * Resolve a meta reference to its ULID
    48→ * Handles semantic IDs (agent.id, workflow.id, convention.domain) and ULID prefixes
    49→ */
    50→function resolveMetaRefToUlid(
    51→  ref: string,
    52→  metaCtx: MetaContext
    53→): { ulid: string; type: 'agent' | 'workflow' | 'convention' | 'observation' } | null {
    54→  const normalizedRef = ref.startsWith('@') ? ref.substring(1) : ref;
    55→
    56→  // Check agents
    57→  const agent = (metaCtx.agents || []).find(
    58→    (a) => a.id === normalizedRef || a._ulid.startsWith(normalizedRef)
    59→  );
    60→  if (agent) return { ulid: agent._ulid, type: 'agent' };
    61→
    62→  // Check workflows
    63→  const workflow = (metaCtx.workflows || []).find(
    64→    (w) => w.id === normalizedRef || w._ulid.startsWith(normalizedRef)
    65→  );
    66→  if (workflow) return { ulid: workflow._ulid, type: 'workflow' };
    67→
    68→  // Check conventions
    69→  const convention = (metaCtx.conventions || []).find(
    70→    (c) => c.domain === normalizedRef || c._ulid.startsWith(normalizedRef)
    71→  );
    72→  if (convention) return { ulid: convention._ulid, type: 'convention' };
    73→
    74→  // Check observations
    75→  const observation = (metaCtx.observations || []).find((o) =>
    76→    o._ulid.startsWith(normalizedRef)
    77→  );
    78→  if (observation) return { ulid: observation._ulid, type: 'observation' };
    79→
    80→  return null;
    81→}
    82→
    83→/**
    84→ * Format meta show output
    85→ */
    86→function formatMetaShow(meta: MetaContext): void {
    87→  const stats = getMetaStats(meta);
    88→
    89→  if (!meta.manifest) {
    90→    console.log(chalk.yellow('No meta manifest found (kynetic.meta.yaml)'));
    91→    console.log(chalk.gray('Create one to define agents, workflows, conventions, and observations'));
    92→    return;
