    expect(result.exitCode).toBe(0);
    const output = JSON.parse(result.stdout);

    expect(output).toHaveProperty('run_id');
    expect(output.workflow_ref).toBe('@01TEST0000000000000000001');
    expect(output.status).toBe('active');

