  // Create a simple workflow for testing
  const metaManifest = {
    kynetic_meta: '1.0',
    workflows: [
      {
        _ulid: '01TEST0000000000000000001',
        id: 'test-workflow',
        trigger: 'manual',
        description: 'Test workflow for run tests',
        steps: [
          {
            type: 'check',
            content: 'Verify prerequisites',
          },
          {
            type: 'action',
            content: 'Execute main task',
          },
          {
            type: 'check',
            content: 'Validate results',
          },
        ],
      },
      {
        _ulid: '01TEST0000000000000000002',
        id: 'another-workflow',
        trigger: 'manual',
        description: 'Another test workflow',
        steps: [
          {
            type: 'action',
            content: 'Do something',
          },
        ],
      },
    ],
  };

  const metaPath = path.join(tempDir, '.kspec', 'kynetic.meta.yaml');
  await fs.writeFile(metaPath, YAML.stringify(metaManifest), 'utf-8');

  // Create a test task for task linking tests
  const tasksFile = {
    kynetic_tasks: '1.0',
    tasks: [
      {
        _ulid: '01TESTTASK000000000000001',
        slugs: ['test-task'],
        title: 'Test Task',
        status: 'pending',
        priority: 3,
        created_at: new Date().toISOString(),
      },
    ],
  };

