/**
 * Tests for workflow run foundation
 * Spec: @workflow-run-foundation
 */
import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { kspec, createTempDir, cleanupTempDir, initGitRepo } from './helpers/cli.js';
