import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { kspec, createTempDir, cleanupTempDir, initGitRepo } from './helpers/cli.js';
import * as fs from 'node:fs/promises';
import * as path from 'node:path';
import * as YAML from 'yaml';
import { parseDocument } from 'yaml';
import { ulid } from 'ulid';

let tempDir: string;
let testWorkflowUlid: string;
let anotherWorkflowUlid: string;
let testTaskUlid: string;

beforeEach(async () => {
  tempDir = await createTempDir();

  // Generate valid ULIDs for test fixtures
  testWorkflowUlid = ulid();
  anotherWorkflowUlid = ulid();
  testTaskUlid = ulid();

  // Initialize git repo (required for shadow operations)
  initGitRepo(tempDir);

  // Create .kspec directory structure
  const kspecDir = path.join(tempDir, '.kspec');
  await fs.mkdir(kspecDir, { recursive: true });

  // Create minimal root manifest
  await fs.writeFile(
    path.join(kspecDir, 'kynetic.yaml'),
    `kynetic: "1.0"
project: Test Project
`,
    'utf-8',
  );

  // Create workflows in meta manifest
  await fs.writeFile(
    path.join(kspecDir, 'kynetic.meta.yaml'),
    `kynetic_meta: "1.0"
workflows:
  - _ulid: ${testWorkflowUlid}
    id: test-workflow
    trigger: manual
    description: Test workflow for run tests
    steps:
      - type: check
        content: Verify prerequisites
      - type: action
        content: Execute main task
      - type: check
        content: Validate results

  - _ulid: ${anotherWorkflowUlid}
    id: another-workflow
    trigger: manual
    description: Another test workflow
    steps:
      - type: action
        content: Do something

agents:
  - _ulid: 01KF79QXTTX8KBRYK14NWV1KYK
    id: test
    name: Test Author
    description: Generic test author
    capabilities: []
    tools: []
    conventions: []
`,
    'utf-8',
  );

  // Create a test task for task linking tests
  await fs.writeFile(
    path.join(kspecDir, 'project.tasks.yaml'),
    `kynetic_tasks: "1.0"
tasks:
  - _ulid: ${testTaskUlid}
    slugs:
      - test-task
    title: Test Task
    status: pending
    priority: 3
    created_at: "${new Date().toISOString()}"
`,
    'utf-8',
  );
});

afterEach(async () => {
  if (tempDir) {
    await cleanupTempDir(tempDir);
  }
});

