  // AC: @cmd-derive ac-15 (variant: multiple parents, one cancelled)
  it('should use non-cancelled parent task when multiple tasks exist', () => {
    // Create a parent spec
    kspec(
      'item add --under @test-core --title "Multi Parent" --slug multi-parent --type feature',
      tempDir
    );

    // Create first task and cancel it
    kspec('derive @multi-parent --flat', tempDir);
    kspec('task cancel @task-multi-parent --reason "cancelled first task"', tempDir);

    // Create second task with --force (should not be cancelled)
    kspec('derive @multi-parent --flat --force', tempDir);

    // Create a child spec
    kspec(
      'item add --under @multi-parent --title "Multi Child" --slug multi-child --type requirement',
      tempDir
    );

    // Derive the child - should use the non-cancelled parent task
    kspec('derive @multi-child', tempDir);

    // Get the child task details
    const taskOutput = kspec('task get @task-multi-child --json', tempDir);
    const task = JSON.parse(taskOutput);

    // Child should depend on the second (non-cancelled) parent task
    // Note: with --force, second task gets slug like "task-multi-parent-1"
    expect(task.depends_on.length).toBe(1);
    expect(task.depends_on[0]).toMatch(/^@task-multi-parent/);

    // Verify it's not the cancelled task
    const parentTaskOutput = kspec('task get @task-multi-parent --json', tempDir);
    const parentTask = JSON.parse(parentTaskOutput);
    expect(parentTask.status).toBe('cancelled');
    expect(task.depends_on[0]).not.toBe('@task-multi-parent');
  });
});

