      'item ac list @test-feature',
      tempDir
    );

    expect(Array.isArray(acList)).toBe(true);
    expect(acList.length).toBe(1);
    expect(acList[0].id).toBe('ac-1');
    expect(acList[0].given).toBe('g');
    expect(acList[0].when).toBe('w');
    expect(acList[0].then).toBe('t');
  });
});

