/**
 * Workflow run CLI commands
 *
 * Implements workflow run lifecycle management:
 * - kspec workflow start @ref [--task @ref] [--json]
 * - kspec workflow runs [--active] [--completed] [--workflow @ref] [--json]
 * - kspec workflow show @run [--json]
 * - kspec workflow abort @run [--reason text] [--json]
 */

import { Command } from 'commander';
import { ulid } from 'ulid';
import chalk from 'chalk';
import Table from 'cli-table3';
import {
  initContext,
  loadMetaContext,
  loadWorkflowRuns,
  saveWorkflowRun,
  updateWorkflowRun,
  findWorkflowRunByRef,
  getAuthor,
  ReferenceIndex,
  loadAllTasks,
  type Workflow,
} from '../../parser/index.js';
import type { WorkflowRun } from '../../schema/index.js';
import { commitIfShadow } from '../../parser/shadow.js';
import { output, success, error, isJsonMode } from '../output.js';
import { errors } from '../../strings/errors.js';
import { EXIT_CODES } from '../exit-codes.js';

/**
 * Find a workflow by reference
 */
function resolveWorkflowRef(ref: string, workflows: Workflow[]): Workflow | null {
  const cleanRef = ref.startsWith('@') ? ref.slice(1) : ref;

  // Try by ID first
  let workflow = workflows.find((w) => w.id === cleanRef);
  if (workflow) return workflow;

  // Try by ULID or ULID prefix
  workflow = workflows.find((w) => w._ulid === cleanRef || w._ulid.toLowerCase().startsWith(cleanRef.toLowerCase()));
  return workflow || null;
}

/**
 * Format a short ULID (first 8 chars)
 */
function shortUlid(ulid: string): string {
  return ulid.slice(0, 8).toUpperCase();
}

/**
 * Format run status with color
 */
function formatStatus(status: string): string {
  switch (status) {
    case 'active':
      return chalk.green(status);
    case 'paused':
      return chalk.yellow(status);
    case 'completed':
      return chalk.blue(status);
    case 'aborted':
      return chalk.red(status);
    default:
      return status;
  }
}

/**
 * Command: kspec workflow start @workflow-ref [--task @task-ref] [--json]
 * AC: @workflow-run-foundation ac-1, ac-6
 */
async function workflowStart(workflowRef: string, options: { task?: string; json?: boolean }) {
  const ctx = await initContext();
  const metaCtx = await loadMetaContext(ctx);

  // DEBUG: Log loaded workflows
  // Resolve workflow reference
  const workflow = resolveWorkflowRef(workflowRef, metaCtx.workflows);
  if (!workflow) {
    error(errors.workflowRun.workflowNotFound(workflowRef));
    process.exit(EXIT_CODES.NOT_FOUND);
  }

  // Validate task reference if provided (AC: @workflow-run-foundation ac-6)
  let taskRef: string | undefined;
  if (options.task) {
    const tasks = await loadAllTasks(ctx);
    const index = new ReferenceIndex(tasks, []);
    const result = index.resolve(options.task);
    if (!result.ok) {
      error(errors.reference.taskNotFound(options.task));
      process.exit(EXIT_CODES.NOT_FOUND);
    }
    taskRef = `@${result.ulid}`;
  }

  // Create new workflow run
  const run: WorkflowRun = {
    _ulid: ulid(),
    workflow_ref: `@${workflow._ulid}`,
    status: 'active',
    current_step: 0,
    total_steps: workflow.steps.length,
    started_at: new Date().toISOString(),
    step_results: [],
    initiated_by: getAuthor(),
    task_ref: taskRef,
  };

  // Save the run
  await saveWorkflowRun(ctx, run);

  // Commit to shadow
  await commitIfShadow(ctx.shadow, 'workflow-start');

  // Output result
  if (isJsonMode()) {
    output({ run_id: run._ulid, workflow_ref: run.workflow_ref, status: run.status });
  } else {
    success(`Started workflow run: ${shortUlid(run._ulid)}`);
    console.log(`  Workflow: ${workflow.id}`);
    console.log(`  Steps: ${run.total_steps}`);
    if (taskRef) {
      console.log(`  Linked task: ${taskRef}`);
    }
  }
}

/**
 * Command: kspec workflow runs [--active] [--completed] [--workflow @ref] [--json]
 * AC: @workflow-run-foundation ac-2
 */
async function workflowRuns(options: {
  active?: boolean;
  completed?: boolean;
  workflow?: string;
  json?: boolean;
}) {
  const ctx = await initContext();
  const metaCtx = await loadMetaContext(ctx);
  let runs = await loadWorkflowRuns(ctx);

  // Apply filters
  if (options.active) {
    runs = runs.filter((r) => r.status === 'active');
  }
  if (options.completed) {
    runs = runs.filter((r) => r.status === 'completed');
  }
  if (options.workflow) {
    const workflow = resolveWorkflowRef(options.workflow, metaCtx.workflows);
    if (!workflow) {
      error(errors.workflowRun.workflowNotFound(options.workflow));
      process.exit(EXIT_CODES.NOT_FOUND);
    }
    runs = runs.filter((r) => r.workflow_ref === `@${workflow._ulid}`);
  }

  if (isJsonMode()) {
    output({ runs });
  } else {
    if (runs.length === 0) {
      console.log(chalk.gray('No workflow runs found'));
      return;
    }

    const table = new Table({
      head: ['ID', 'Workflow', 'Status', 'Step', 'Started'],
      colWidths: [12, 25, 12, 10, 20],
    });

    for (const run of runs) {
      const workflow = metaCtx.workflows.find((w) => `@${w._ulid}` === run.workflow_ref);
      const workflowName = workflow?.id || run.workflow_ref;
      const stepProgress = `${run.current_step}/${run.total_steps}`;
      const started = new Date(run.started_at).toLocaleString();

      table.push([
        shortUlid(run._ulid),
        workflowName,
        formatStatus(run.status),
        stepProgress,
        started,
      ]);
    }

    console.log(table.toString());
  }
}

/**
 * Command: kspec workflow show @run-id [--json]
 * AC: @workflow-run-foundation ac-4
 */
async function workflowShow(runRef: string, options: { json?: boolean }) {
  const ctx = await initContext();
  const metaCtx = await loadMetaContext(ctx);

  const run = await findWorkflowRunByRef(ctx, runRef);
  if (!run) {
    error(errors.workflowRun.runNotFound(runRef));
    process.exit(EXIT_CODES.NOT_FOUND);
  }

  if (isJsonMode()) {
    output({ run });
  } else {
    const workflow = metaCtx.workflows.find((w) => `@${w._ulid}` === run.workflow_ref);
    const workflowName = workflow?.id || run.workflow_ref;

    console.log(chalk.bold('Workflow Run Details'));
    console.log(chalk.gray('─'.repeat(50)));
    console.log(`ID:           ${shortUlid(run._ulid)}`);
    console.log(`Workflow:     ${workflowName} (${run.workflow_ref})`);
    console.log(`Status:       ${formatStatus(run.status)}`);
    console.log(`Progress:     ${run.current_step}/${run.total_steps}`);
    console.log(`Started:      ${new Date(run.started_at).toLocaleString()}`);

    if (run.initiated_by) {
      console.log(`Initiated by: ${run.initiated_by}`);
    }
    if (run.task_ref) {
      console.log(`Task:         ${run.task_ref}`);
    }
    if (run.paused_at) {
      console.log(`Paused:       ${new Date(run.paused_at).toLocaleString()}`);
    }
    if (run.completed_at) {
      console.log(`Completed:    ${new Date(run.completed_at).toLocaleString()}`);
    }
    if (run.abort_reason) {
      console.log(`Abort reason: ${run.abort_reason}`);
    }

    if (run.step_results.length > 0) {
      console.log(chalk.gray('\nStep Results:'));
      const table = new Table({
        head: ['Step', 'Status', 'Started', 'Completed'],
        colWidths: [8, 12, 20, 20],
      });

      for (const result of run.step_results) {
        table.push([
          result.step_index.toString(),
          formatStatus(result.status),
          new Date(result.started_at).toLocaleString(),
          new Date(result.completed_at).toLocaleString(),
        ]);
      }

      console.log(table.toString());
    }
  }
}

/**
 * Command: kspec workflow abort @run-id [--reason text] [--json]
 * AC: @workflow-run-foundation ac-3, ac-5
 */
async function workflowAbort(runRef: string, options: { reason?: string; json?: boolean }) {
  const ctx = await initContext();

  const run = await findWorkflowRunByRef(ctx, runRef);
  if (!run) {
    error(errors.workflowRun.runNotFound(runRef));
    process.exit(EXIT_CODES.NOT_FOUND);
  }

  // AC: @workflow-run-foundation ac-5 - Cannot abort completed or aborted runs
  if (run.status === 'completed') {
    error(errors.workflowRun.cannotAbortCompleted);
    process.exit(EXIT_CODES.VALIDATION_FAILED);
  }

  if (run.status === 'aborted') {
    error(errors.workflowRun.cannotAbortAborted);
    process.exit(EXIT_CODES.VALIDATION_FAILED);
  }

  // Update run status
  run.status = 'aborted';
  run.abort_reason = options.reason;
  run.completed_at = new Date().toISOString();

  await updateWorkflowRun(ctx, run);
  await commitIfShadow(ctx.shadow, 'workflow-abort');

  if (isJsonMode()) {
    output({ run_id: run._ulid, status: run.status });
  } else {
    success(`Aborted workflow run: ${shortUlid(run._ulid)}`);
    if (options.reason) {
      console.log(`  Reason: ${options.reason}`);
    }
  }
}

/**
 * Register workflow commands
 */
export function registerWorkflowCommand(program: Command): void {
  const workflow = program
    .command('workflow')
    .description('Manage workflow runs');

  workflow
    .command('start')
    .description('Start a new workflow run')
    .argument('<workflow-ref>', 'Workflow reference (@id or @ulid)')
    .option('--task <task-ref>', 'Link run to a task')
    .option('--json', 'Output JSON')
    .action(workflowStart);

  workflow
    .command('runs')
    .description('List workflow runs')
    .option('--active', 'Show only active runs')
    .option('--completed', 'Show only completed runs')
    .option('--workflow <ref>', 'Filter by workflow')
    .option('--json', 'Output JSON')
    .action(workflowRuns);

  workflow
    .command('show')
    .description('Show workflow run details')
    .argument('<run-ref>', 'Run reference (@ulid or ulid prefix)')
    .option('--json', 'Output JSON')
    .action(workflowShow);

  workflow
    .command('abort')
    .description('Abort an active workflow run')
    .argument('<run-ref>', 'Run reference (@ulid or ulid prefix)')
    .option('--reason <text>', 'Reason for aborting')
    .option('--json', 'Output JSON')
    .action(workflowAbort);
}

/**
 * Meta manifest loading and operations.
 *
 * The meta manifest (kynetic.meta.yaml) contains process definitions:
 * - Agents: roles, capabilities, conventions
 * - Workflows: structured processes with steps
 * - Conventions: project rules and standards
 * - Observations: feedback about processes
 */

import * as fs from 'node:fs/promises';
import * as path from 'node:path';
import { ulid } from 'ulid';
import {
  MetaManifestSchema,
  AgentSchema,
  WorkflowSchema,
  ConventionSchema,
  ObservationSchema,
  SessionContextSchema,
  WorkflowRunsFileSchema,
  WorkflowRunSchema,
  type MetaManifest,
  type Agent,
  type Workflow,
  type Convention,
  type Observation,
  type MetaItem,
  type ObservationType,
  type SessionContext,
  type WorkflowRun,
  type WorkflowRunsFile,
  getMetaItemType,
} from '../schema/index.js';
import { readYamlFile, writeYamlFilePreserveFormat, expandIncludePattern, getAuthor } from './yaml.js';
import type { KspecContext } from './yaml.js';

/**
 * Loaded agent with runtime metadata
 */
export interface LoadedAgent extends Agent {
  _sourceFile?: string;
}

/**
 * Loaded workflow with runtime metadata
 */
export interface LoadedWorkflow extends Workflow {
  _sourceFile?: string;
}

/**
 * Loaded convention with runtime metadata
 */
export interface LoadedConvention extends Convention {
  _sourceFile?: string;
}

/**
 * Loaded observation with runtime metadata
 */
export interface LoadedObservation extends Observation {
  _sourceFile?: string;
}

/**
 * Any loaded meta item
 */
export type LoadedMetaItem = LoadedAgent | LoadedWorkflow | LoadedConvention | LoadedObservation;

/**
 * Meta context containing all loaded meta items
 */
export interface MetaContext {
  manifest: MetaManifest | null;
  manifestPath: string | null;
  agents: LoadedAgent[];
  workflows: LoadedWorkflow[];
  conventions: LoadedConvention[];
  observations: LoadedObservation[];
}

/**
 * Find the meta manifest file (kynetic.meta.yaml)
 */
export async function findMetaManifest(specDir: string): Promise<string | null> {
  const candidates = ['kynetic.meta.yaml'];

  for (const candidate of candidates) {
    const filePath = path.join(specDir, candidate);
    try {
      await fs.access(filePath);
      return filePath;
    } catch {
      // File doesn't exist, try next
    }
  }

  return null;
}

/**
 * Get the meta manifest file path.
 * Returns path even if file doesn't exist yet.
 */
export function getMetaManifestPath(ctx: KspecContext): string {
  return path.join(ctx.specDir, 'kynetic.meta.yaml');
}

/**
 * Load meta items from a single file.
 */
async function loadMetaFile(
  filePath: string
): Promise<{
  agents: LoadedAgent[];
  workflows: LoadedWorkflow[];
  conventions: LoadedConvention[];
  observations: LoadedObservation[];
}> {
  const result: {
    agents: LoadedAgent[];
    workflows: LoadedWorkflow[];
    conventions: LoadedConvention[];
    observations: LoadedObservation[];
  } = {
    agents: [],
    workflows: [],
    conventions: [],
    observations: [],
  };

  try {
    const raw = await readYamlFile<unknown>(filePath);
    if (!raw || typeof raw !== 'object') {
      return result;
    }

    const obj = raw as Record<string, unknown>;

    // Parse agents
    if (Array.isArray(obj.agents)) {
      for (const agent of obj.agents) {
        const parsed = AgentSchema.safeParse(agent);
        if (parsed.success) {
          result.agents.push({ ...parsed.data, _sourceFile: filePath });
        }
      }
    }

    // Parse workflows
    if (Array.isArray(obj.workflows)) {
      for (const workflow of obj.workflows) {
        const parsed = WorkflowSchema.safeParse(workflow);
        if (parsed.success) {
          result.workflows.push({ ...parsed.data, _sourceFile: filePath });
        }
      }
    }

    // Parse conventions
    if (Array.isArray(obj.conventions)) {
      for (const convention of obj.conventions) {
        const parsed = ConventionSchema.safeParse(convention);
        if (parsed.success) {
          result.conventions.push({ ...parsed.data, _sourceFile: filePath });
        }
      }
    }

    // Parse observations
    if (Array.isArray(obj.observations)) {
      for (const observation of obj.observations) {
        const parsed = ObservationSchema.safeParse(observation);
        if (parsed.success) {
          result.observations.push({ ...parsed.data, _sourceFile: filePath });
        }
      }
    }
  } catch {
    // File doesn't exist or parse error
  }

  return result;
}

/**
 * Load the meta context from a kspec context.
 * Loads meta manifest and follows includes.
 */
export async function loadMetaContext(ctx: KspecContext): Promise<MetaContext> {
  const result: MetaContext = {
    manifest: null,
    manifestPath: null,
    agents: [],
    workflows: [],
    conventions: [],
    observations: [],
  };

  const manifestPath = await findMetaManifest(ctx.specDir);
  if (!manifestPath) {
    return result;
  }

  result.manifestPath = manifestPath;

  try {
    const raw = await readYamlFile<unknown>(manifestPath);
    const parsed = MetaManifestSchema.safeParse(raw);
    if (!parsed.success) {
      // Invalid manifest, but we can still try to extract items
      const items = await loadMetaFile(manifestPath);
      result.agents.push(...items.agents);
      result.workflows.push(...items.workflows);
      result.conventions.push(...items.conventions);
      result.observations.push(...items.observations);
      return result;
    }

    result.manifest = parsed.data;

    // Load items from manifest
    const manifestItems = await loadMetaFile(manifestPath);
    result.agents.push(...manifestItems.agents);
    result.workflows.push(...manifestItems.workflows);
    result.conventions.push(...manifestItems.conventions);
    result.observations.push(...manifestItems.observations);

    // Process includes
    const includes = parsed.data.includes || [];
    const manifestDir = path.dirname(manifestPath);

    for (const include of includes) {
      const expandedPaths = await expandIncludePattern(include, manifestDir);

      for (const filePath of expandedPaths) {
        const items = await loadMetaFile(filePath);
        result.agents.push(...items.agents);
        result.workflows.push(...items.workflows);
        result.conventions.push(...items.conventions);
        result.observations.push(...items.observations);
      }
    }
  } catch {
    // Manifest exists but may be invalid
  }

  return result;
}

/**
 * Get meta stats summary
 */
export function getMetaStats(meta: MetaContext): {
  agents: number;
  workflows: number;
  conventions: number;
  observations: number;
  unresolvedObservations: number;
} {
  return {
    agents: meta.agents.length,
    workflows: meta.workflows.length,
    conventions: meta.conventions.length,
    observations: meta.observations.length,
    unresolvedObservations: meta.observations.filter((o) => !o.resolved).length,
  };
}

/**
 * Find a meta item by reference (ULID, short ULID, or id)
 */
export function findMetaItemByRef(
  meta: MetaContext,
  ref: string
): LoadedMetaItem | undefined {
  const cleanRef = ref.startsWith('@') ? ref.slice(1) : ref;

  // Search all item types
  const allItems: LoadedMetaItem[] = [
    ...meta.agents,
    ...meta.workflows,
    ...meta.conventions,
    ...meta.observations,
  ];

  for (const item of allItems) {
    // Match full ULID
    if (item._ulid === cleanRef) return item;

    // Match short ULID (prefix)
    if (item._ulid.toLowerCase().startsWith(cleanRef.toLowerCase())) return item;

    // Match by id (for agents and workflows)
    if ('id' in item && item.id === cleanRef) return item;

    // Match by domain (for conventions)
    if ('domain' in item && item.domain === cleanRef) return item;
  }

  return undefined;
}

/**
 * Determine if an item is a meta item type
 */
export function isMetaItemType(type: string): boolean {
  return ['agent', 'workflow', 'convention', 'observation'].includes(type);
}

// ============================================================
// META ITEM CRUD
// ============================================================

/**
 * Save the entire meta manifest to file
 */
async function saveMetaManifest(
  manifestPath: string,
  manifest: MetaManifest
): Promise<void> {
  await writeYamlFilePreserveFormat(manifestPath, manifest);
}

/**
 * Strip runtime metadata before serialization
 */
function stripMetaMetadata<T extends LoadedMetaItem>(item: T): Omit<T, '_sourceFile'> {
  const { _sourceFile, ...cleanItem } = item;
  return cleanItem as Omit<T, '_sourceFile'>;
}

/**
 * Create a new observation
 */
export function createObservation(
  type: ObservationType,
  content: string,
  options: {
    workflow_ref?: string;
    author?: string;
  } = {}
): Observation {
  return {
    _ulid: ulid(),
    type,
    content,
    workflow_ref: options.workflow_ref,
    created_at: new Date().toISOString(),
    author: options.author ?? getAuthor(),
    resolved: false,
    resolution: null,
  };
}

/**
 * Save an observation to the meta manifest
 */
export async function saveObservation(
  ctx: KspecContext,
  observation: LoadedObservation
): Promise<void> {
  const manifestPath = getMetaManifestPath(ctx);

  // Ensure directory exists
  const dir = path.dirname(manifestPath);
  await fs.mkdir(dir, { recursive: true });

  // Load existing manifest
  let manifest: MetaManifest = {
    kynetic_meta: '1.0',
    agents: [],
    workflows: [],
    conventions: [],
    observations: [],
    includes: [],
  };

  try {
    const raw = await readYamlFile<unknown>(manifestPath);
    const parsed = MetaManifestSchema.safeParse(raw);
    if (parsed.success) {
      manifest = parsed.data;
    }
  } catch {
    // File doesn't exist, use defaults
  }

  // Strip runtime metadata
  const cleanObs = stripMetaMetadata(observation);

  // Update or add
  const existingIndex = manifest.observations.findIndex(
    (o) => o._ulid === observation._ulid
  );
  if (existingIndex >= 0) {
    manifest.observations[existingIndex] = cleanObs as Observation;
  } else {
    manifest.observations.push(cleanObs as Observation);
  }

  await saveMetaManifest(manifestPath, manifest);
}

/**
 * Delete an observation from the meta manifest
 */
export async function deleteObservation(
  ctx: KspecContext,
  ulid: string
): Promise<boolean> {
  const manifestPath = getMetaManifestPath(ctx);

  try {
    const raw = await readYamlFile<unknown>(manifestPath);
    const parsed = MetaManifestSchema.safeParse(raw);
    if (!parsed.success) {
      return false;
    }

    const manifest = parsed.data;
    const index = manifest.observations.findIndex((o) => o._ulid === ulid);
    if (index < 0) {
      return false;
    }

    manifest.observations.splice(index, 1);
    await saveMetaManifest(manifestPath, manifest);
    return true;
  } catch {
    return false;
  }
}

// Re-export the getMetaItemType function
export { getMetaItemType };
export type { Agent, Workflow, Convention, Observation, MetaItem };

// ============================================================
// GENERIC META ITEM CRUD
// ============================================================

/**
 * Save any meta item (agent, workflow, convention) to the manifest
 */
export async function saveMetaItem(
  ctx: KspecContext,
  item: LoadedMetaItem,
  itemType: 'agent' | 'workflow' | 'convention'
): Promise<void> {
  const manifestPath = getMetaManifestPath(ctx);

  // Ensure directory exists
  const dir = path.dirname(manifestPath);
  await fs.mkdir(dir, { recursive: true });

  // Load existing manifest
  let manifest: MetaManifest = {
    kynetic_meta: '1.0',
    agents: [],
    workflows: [],
    conventions: [],
    observations: [],
    includes: [],
  };

  try {
    const raw = await readYamlFile<unknown>(manifestPath);
    const parsed = MetaManifestSchema.safeParse(raw);
    if (parsed.success) {
      manifest = parsed.data;
    }
  } catch {
    // File doesn't exist, use defaults
  }

  // Strip runtime metadata
  const cleanItem = stripMetaMetadata(item);

  // Get the appropriate array
  const getArray = () => {
    switch (itemType) {
      case 'agent':
        return manifest.agents;
      case 'workflow':
        return manifest.workflows;
      case 'convention':
        return manifest.conventions;
    }
  };

  const array = getArray();

  // Update or add
  const existingIndex = array.findIndex((i) => i._ulid === item._ulid);
  if (existingIndex >= 0) {
    (array as unknown[])[existingIndex] = cleanItem;
  } else {
    (array as unknown[]).push(cleanItem);
  }

  await saveMetaManifest(manifestPath, manifest);
}

/**
 * Delete any meta item from the manifest
 */
export async function deleteMetaItem(
  ctx: KspecContext,
  itemUlid: string,
  itemType: 'agent' | 'workflow' | 'convention' | 'observation'
): Promise<boolean> {
  const manifestPath = getMetaManifestPath(ctx);

  try {
    const raw = await readYamlFile<unknown>(manifestPath);
    const parsed = MetaManifestSchema.safeParse(raw);
    if (!parsed.success) {
      return false;
    }

    const manifest = parsed.data;

    const getArray = () => {
      switch (itemType) {
        case 'agent':
          return manifest.agents;
        case 'workflow':
          return manifest.workflows;
        case 'convention':
          return manifest.conventions;
        case 'observation':
          return manifest.observations;
      }
    };

    const array = getArray();
    const index = array.findIndex((i) => i._ulid === itemUlid);
    if (index < 0) {
      return false;
    }

    array.splice(index, 1);
    await saveMetaManifest(manifestPath, manifest);
    return true;
  } catch {
    return false;
  }
}

// ============================================================
// SESSION CONTEXT
// ============================================================

/**
 * Get the session context file path
 */
export function getSessionContextPath(ctx: KspecContext): string {
  return path.join(ctx.specDir, '.kspec-session');
}

/**
 * Load session context (or return empty context if not exists)
 */
export async function loadSessionContext(ctx: KspecContext): Promise<SessionContext> {
  const contextPath = getSessionContextPath(ctx);

  try {
    const raw = await readYamlFile<unknown>(contextPath);
    if (!raw || typeof raw !== 'object') {
      return {
        focus: null,
        threads: [],
        open_questions: [],
        updated_at: new Date().toISOString(),
      };
    }

    // Validate and parse using schema
    const result = SessionContextSchema.safeParse(raw);
    if (result.success) {
      return result.data;
    }

    // If validation fails, return empty context
    return {
      focus: null,
      threads: [],
      open_questions: [],
      updated_at: new Date().toISOString(),
    };
  } catch {
    return {
      focus: null,
      threads: [],
      open_questions: [],
      updated_at: new Date().toISOString(),
    };
  }
}

/**
 * Save session context
 */
export async function saveSessionContext(ctx: KspecContext, context: SessionContext): Promise<void> {
  const contextPath = getSessionContextPath(ctx);

  // Update timestamp
  context.updated_at = new Date().toISOString();

  await writeYamlFilePreserveFormat(contextPath, context);
}

// ============================================================
// WORKFLOW RUNS
// ============================================================

/**
 * Get the workflow runs file path
 */
export function getWorkflowRunsPath(ctx: KspecContext): string {
  return path.join(ctx.specDir, 'kynetic.runs.yaml');
}

/**
 * Load workflow runs from file
 */
export async function loadWorkflowRuns(ctx: KspecContext): Promise<WorkflowRun[]> {
  const runsPath = getWorkflowRunsPath(ctx);

  try {
    const raw = await readYamlFile<unknown>(runsPath);
    const parsed = WorkflowRunsFileSchema.safeParse(raw);

    if (!parsed.success) {
      return [];
    }

    return parsed.data.runs;
  } catch {
    // File doesn't exist
    return [];
  }
}

/**
 * Save a workflow run (create or update)
 */
export async function saveWorkflowRun(ctx: KspecContext, run: WorkflowRun): Promise<void> {
  const runsPath = getWorkflowRunsPath(ctx);

  // Load existing runs
  const runs = await loadWorkflowRuns(ctx);

  // Update or add
  const existingIndex = runs.findIndex((r) => r._ulid === run._ulid);
  if (existingIndex >= 0) {
    runs[existingIndex] = run;
  } else {
    runs.push(run);
  }

  // Save back
  const runsFile: WorkflowRunsFile = {
    kynetic_runs: '1.0',
    runs,
  };

  await writeYamlFilePreserveFormat(runsPath, runsFile);
}

/**
 * Update an existing workflow run
 */
export async function updateWorkflowRun(ctx: KspecContext, run: WorkflowRun): Promise<void> {
  await saveWorkflowRun(ctx, run);
}

/**
 * Find a workflow run by reference (ULID or ULID prefix)
 */
export async function findWorkflowRunByRef(
  ctx: KspecContext,
  ref: string
): Promise<WorkflowRun | undefined> {
  const runs = await loadWorkflowRuns(ctx);
  const cleanRef = ref.startsWith('@') ? ref.slice(1) : ref;

  return runs.find((r) => r._ulid === cleanRef || r._ulid.toLowerCase().startsWith(cleanRef.toLowerCase()));
}

