   231→      console.log(`Paused:       ${new Date(run.paused_at).toLocaleString()}`);
   232→    }
   233→    if (run.completed_at) {
   234→      console.log(`Completed:    ${new Date(run.completed_at).toLocaleString()}`);
   235→    }
   236→    if (run.abort_reason) {
   237→      console.log(`Abort reason: ${run.abort_reason}`);
   238→    }
   239→
   240→    if (run.step_results.length > 0) {
   241→      console.log(chalk.gray('\nStep Results:'));
   242→      const table = new Table({
   243→        head: ['Step', 'Status', 'Started', 'Completed'],
   244→        colWidths: [8, 12, 20, 20],
   245→      });
   246→
   247→      for (const result of run.step_results) {
   248→        table.push([
   249→          result.step_index.toString(),
   250→          formatStatus(result.status),
   251→          new Date(result.started_at).toLocaleString(),
   252→          new Date(result.completed_at).toLocaleString(),
   253→        ]);
   254→      }
   255→
   256→      console.log(table.toString());
   257→    }
   258→  }
   259→}
   260→
   261→/**
   262→ * Command: kspec workflow abort @run-id [--reason text] [--json]
   263→ * AC: @workflow-run-foundation ac-3, ac-5
   264→ */
   265→async function workflowAbort(runRef: string, options: { reason?: string; json?: boolean }) {
   266→  const ctx = await initContext();
   267→
   268→  const run = await findWorkflowRunByRef(ctx, runRef);
   269→  if (!run) {
   270→    error(errors.workflowRun.runNotFound(runRef));
   271→    process.exit(EXIT_CODES.NOT_FOUND);
   272→  }
   273→
   274→  // AC: @workflow-run-foundation ac-5 - Cannot abort completed or aborted runs
   275→  if (run.status === 'completed') {
   276→    error(errors.workflowRun.cannotAbortCompleted);
   277→    process.exit(EXIT_CODES.VALIDATION_FAILED);
   278→  }
   279→
   280→  if (run.status === 'aborted') {
   281→    error(errors.workflowRun.cannotAbortAborted);
   282→    process.exit(EXIT_CODES.VALIDATION_FAILED);
   283→  }
   284→
   285→  // Update run status
   286→  run.status = 'aborted';
   287→  run.abort_reason = options.reason;
   288→  run.completed_at = new Date().toISOString();
   289→
   290→  await updateWorkflowRun(ctx, run);
   291→  await commitIfShadow(ctx.shadow, 'workflow-abort');
   292→
   293→  if (isJsonMode()) {
   294→    output({ run_id: run._ulid, status: run.status });
   295→  } else {
   296→    success(`Aborted workflow run: ${shortUlid(run._ulid)}`);
   297→    if (options.reason) {
   298→      console.log(`  Reason: ${options.reason}`);
   299→    }
   300→  }
   301→}
   302→
   303→/**
   304→ * Register workflow commands
   305→ */
   306→export function registerWorkflowCommand(program: Command): void {
   307→  const workflow = program
   308→    .command('workflow')
   309→    .description('Manage workflow runs');
   310→
   311→  workflow
   312→    .command('start')
   313→    .description('Start a new workflow run')
   314→    .argument('<workflow-ref>', 'Workflow reference (@id or @ulid)')
   315→    .option('--task <task-ref>', 'Link run to a task')
   316→    .option('--json', 'Output JSON')
   317→    .action(workflowStart);
   318→
   319→  workflow
   320→    .command('runs')
   321→    .description('List workflow runs')
   322→    .option('--active', 'Show only active runs')
   323→    .option('--completed', 'Show only completed runs')
   324→    .option('--workflow <ref>', 'Filter by workflow')
   325→    .option('--json', 'Output JSON')
   326→    .action(workflowRuns);
   327→
   328→  workflow
   329→    .command('show')
   330→    .description('Show workflow run details')
   331→    .argument('<run-ref>', 'Run reference (@ulid or ulid prefix)')
   332→    .option('--json', 'Output JSON')
   333→    .action(workflowShow);
   334→
   335→  workflow
   336→    .command('abort')
   337→    .description('Abort an active workflow run')
   338→    .argument('<run-ref>', 'Run reference (@ulid or ulid prefix)')
   339→    .option('--reason <text>', 'Reason for aborting')
   340→    .option('--json', 'Output JSON')
   341→    .action(workflowAbort);
   342→}
