    97→    return;
    98→  }
    99→
   100→  sessionId = `mock-session-${Date.now()}`;
   101→  sendResponse(id, { sessionId });
   102→}
   103→
   104→async function handlePrompt(id, params) {
   105→  if (!initialized) {
   106→    sendError(id, -32002, 'Not initialized');
   107→    return;
   108→  }
   109→
   110→  if (!sessionId || params.sessionId !== sessionId) {
   111→    sendError(id, -32003, 'Invalid session');
   112→    return;
   113→  }
   114→
   115→  // Optional delay
   116→  if (delayMs > 0) {
   117→    await new Promise((resolve) => setTimeout(resolve, delayMs));
   118→  }
   119→
   120→  // Check if we should fail
   121→  if (shouldFail()) {
   122→    sendError(id, -32000, 'Mock failure');
   123→    return;
   124→  }
   125→
   126→  // Send streaming update notification (ACP SessionUpdate format)
   127→  // SessionUpdate is a discriminated union with sessionUpdate as the discriminator
   128→  sendNotification('session/update', {
   129→    sessionId,
   130→    update: {
   131→      sessionUpdate: 'agent_message_chunk',
   132→      content: { type: 'text', text: responseText },
   133→    },
   134→  });
   135→
   136→  // Send completion response
   137→  sendResponse(id, { stopReason });
   138→}
   139→
   140→// ─── Message Router ──────────────────────────────────────────────────────────
   141→
   142→async function handleMessage(line) {
   143→  try {
   144→    const msg = JSON.parse(line);
   145→
   146→    if (msg.jsonrpc !== '2.0' || !msg.method) {
   147→      sendError(msg.id || null, -32600, 'Invalid Request');
   148→      return;
   149→    }
   150→
   151→    switch (msg.method) {
   152→      case 'initialize':
   153→        await handleInitialize(msg.id, msg.params);
   154→        break;
   155→      case 'session/new':
   156→        await handleNewSession(msg.id, msg.params);
   157→        break;
   158→      case 'session/prompt':
   159→        await handlePrompt(msg.id, msg.params);
   160→        break;
   161→      default:
   162→        sendError(msg.id, -32601, `Method not found: ${msg.method}`);
   163→    }
   164→  } catch (err) {
   165→    sendError(null, -32700, 'Parse error');
   166→  }
   167→}
   168→
   169→// ─── Main ────────────────────────────────────────────────────────────────────
   170→
   171→const rl = readline.createInterface({
   172→  input: process.stdin,
   173→  output: process.stdout,
   174→  terminal: false,
   175→});
   176→
   177→rl.on('line', (line) => {
   178→  if (line.trim()) {
   179→    handleMessage(line).catch((err) => {
   180→      console.error('Mock ACP error:', err.message);
   181→    });
   182→  }
   183→});
   184→
   185→rl.on('close', () => {
   186→  process.exit(0);
   187→});
   188→

