    41→/**
    42→ * Options for ACPClient
    43→ */
    44→export interface ACPClientOptions extends JsonRpcFramingOptions {
    45→  /** Client capabilities to advertise */
    46→  capabilities?: ClientCapabilities;
    47→  /** Client info */
    48→  clientInfo?: {
    49→    name: string;
    50→    version?: string;
    51→  };
    52→}
    53→
    54→// Event types for type-safe event handling
    55→export interface ACPClientEvents {
    56→  update: (sessionId: string, update: SessionUpdate) => void;
    57→  request: (id: string | number, method: string, params: unknown) => void;
    58→  close: () => void;
    59→  error: (error: Error) => void;
