    61→
    62→/**
    63→ * ACP Client
    64→ *
    65→ * Manages agent communication over JSON-RPC 2.0 stdio transport.
    66→ * Handles initialization, session lifecycle, prompts, and streaming updates.
    67→ *
    68→ * Events:
    69→ * - 'update': Emitted when session updates arrive (sessionId, update)
    70→ * - 'close': Emitted when the connection is closed
    71→ * - 'error': Emitted on errors
    72→ */
    73→export class ACPClient extends EventEmitter {
    74→  private framing: JsonRpcFraming;
    75→  private sessions = new Map<string, SessionState>();
    76→  private agentCapabilities: AgentCapabilities = {};
    77→  private clientCapabilities: ClientCapabilities;
    78→  private clientInfo?: { name: string; version?: string };
    79→  private initialized = false;
    80→
    81→  constructor(options: ACPClientOptions = {}) {
    82→    super();
    83→
    84→    // Default capabilities - we don't handle file/terminal in this simplified client
    85→    this.clientCapabilities = options.capabilities ?? {};
    86→    this.clientInfo = options.clientInfo;
    87→
    88→    // Create framing layer
    89→    this.framing = new JsonRpcFraming(options);
    90→
    91→    // Wire up notification handler for session updates
    92→    this.framing.on("notification", (notification: JsonRpcNotification) => {
    93→      this.handleNotification(notification);
    94→    });
    95→
    96→    // Forward request events for tool calls
    97→    this.framing.on("request", (request: JsonRpcRequest) => {
    98→      this.emit("request", request.id, request.method, request.params);
    99→    });
   100→
   101→    // Forward framing events
   102→    this.framing.on("close", () => this.emit("close"));
   103→    this.framing.on("error", (err: Error) => this.emit("error", err));
   104→  }
   105→
   106→  /**
   107→   * Initialize the agent connection
   108→   *
   109→   * @returns Agent capabilities including supported features
   110→   * @throws If already initialized or connection fails
   111→   */
   112→  async initialize(): Promise<AgentCapabilities> {
   113→    if (this.initialized) {
   114→      throw new Error("Client already initialized");
   115→    }
   116→
   117→    const params: InitializeRequest = {
   118→      protocolVersion: 1,
   119→      clientCapabilities: this.clientCapabilities,
   120→      ...(this.clientInfo && {
   121→        clientInfo: {
   122→          name: this.clientInfo.name,
   123→          version: this.clientInfo.version ?? "0.0.0",
   124→        },
   125→      }),
   126→    };
   127→
   128→    const result = (await this.framing.sendRequest(
   129→      "initialize",
   130→      params,
   131→    )) as InitializeResponse;
   132→
   133→    this.agentCapabilities = result.agentCapabilities ?? {};
   134→    this.initialized = true;
   135→
   136→    return this.agentCapabilities;
   137→  }
   138→
   139→  /**
   140→   * Create a new session
   141→   *
   142→   * @param params Session parameters including cwd and optional metadata
   143→   * @returns Session ID
   144→   * @throws If not initialized or session creation fails
   145→   */
   146→  async newSession(params: NewSessionRequest): Promise<string> {
   147→    if (!this.initialized) {
   148→      throw new Error("Client not initialized");
   149→    }
   150→
   151→    const result = (await this.framing.sendRequest(
   152→      "session/new",
   153→      params,
   154→    )) as NewSessionResponse;
   155→
   156→    // Track session state
   157→    this.sessions.set(result.sessionId, {
   158→      id: result.sessionId,
   159→      status: "idle",
   160→    });
   161→
   162→    return result.sessionId;
   163→  }
   164→
   165→  /**
   166→   * Send a prompt to the agent
   167→   *
   168→   * @param params Prompt request parameters including sessionId and prompt content
   169→   * @returns Prompt response with stopReason
   170→   * @throws If not initialized, session not found, or already prompting
   171→   */
   172→  async prompt(params: PromptRequest): Promise<PromptResponse> {
   173→    if (!this.initialized) {
   174→      throw new Error("Client not initialized");
   175→    }
   176→
   177→    const session = this.sessions.get(params.sessionId);
   178→    if (!session) {
   179→      throw new Error(`Session not found: ${params.sessionId}`);
   180→    }
   181→
   182→    if (session.status === "prompting") {
   183→      throw new Error(`Session already prompting: ${params.sessionId}`);
   184→    }
   185→
   186→    // Update session state
   187→    session.status = "prompting";
   188→
   189→    try {
   190→      const result = (await this.framing.sendRequest(
   191→        "session/prompt",
   192→        params,
   193→      )) as PromptResponse;
   194→
   195→      // Update session state based on stop reason
   196→      if (result.stopReason === "cancelled") {
   197→        session.status = "cancelled";
   198→      } else {
   199→        session.status = "idle";
   200→      }
   201→
   202→      return result;
   203→    } catch (err) {
   204→      // Reset to idle on error
   205→      session.status = "idle";
   206→      throw err;
   207→    }
   208→  }
   209→
   210→  /**
   211→   * Cancel an ongoing prompt
   212→   *
   213→   * Note: session/cancel is an optional ACP method. If the agent doesn't
   214→   * support it (returns "Method not found"), we silently ignore the error.
   215→   * The caller should fall back to process termination (SIGTERM) if needed.
   216→   *
   217→   * @param sessionId The session to cancel
   218→   * @throws If not initialized or session not found
   219→   */
   220→  async cancel(sessionId: string): Promise<void> {
   221→    if (!this.initialized) {
   222→      throw new Error("Client not initialized");
   223→    }
   224→
   225→    const session = this.sessions.get(sessionId);
   226→    if (!session) {
   227→      throw new Error(`Session not found: ${sessionId}`);
   228→    }
   229→
   230→    try {
   231→      // Use silentMethodNotFound since not all agents implement session/cancel
   232→      await this.framing.sendRequest(
   233→        "session/cancel",
   234→        { sessionId },
   235→        { silentMethodNotFound: true },
   236→      );
   237→
   238→      // Update session state
   239→      session.status = "cancelled";
   240→    } catch (err: unknown) {
   241→      // Ignore "Method not found" errors - agent doesn't support cancel
   242→      const error = err as { code?: number };
   243→      if (error.code === -32601) {
   244→        // Agent doesn't support session/cancel, caller should use SIGTERM
   245→        return;
   246→      }
   247→      throw err;
   248→    }
   249→  }
   250→
   251→  /**
   252→   * Get session state
   253→   *
   254→   * @param sessionId The session to get
   255→   * @returns Session state or undefined if not found
   256→   */
   257→  getSession(sessionId: string): SessionState | undefined {
   258→    return this.sessions.get(sessionId);
   259→  }
   260→
   261→  /**
   262→   * Get all sessions
   263→   *
   264→   * @returns Array of all session states
   265→   */
   266→  getAllSessions(): SessionState[] {
   267→    return Array.from(this.sessions.values());
   268→  }
   269→
   270→  /**
   271→   * Get agent capabilities (available after initialize)
   272→   *
   273→   * @returns Agent capabilities
   274→   */
   275→  getCapabilities(): AgentCapabilities {
   276→    return this.agentCapabilities;
   277→  }
   278→
   279→  /**
   280→   * Check if client is initialized
   281→   *
   282→   * @returns true if initialize() has been called successfully
   283→   */
   284→  isInitialized(): boolean {
   285→    return this.initialized;
   286→  }
   287→
   288→  /**
   289→   * Check if the client connection is closed
   290→   *
   291→   * @returns true if the connection is closed
   292→   */
   293→  isClosed(): boolean {
   294→    return this.framing.isClosed();
   295→  }
   296→
   297→  /**
   298→   * Send a response to an agent request (tool call)
   299→   *
   300→   * Prefer typed response methods (respondPermission, etc.) when available.
   301→   *
   302→   * @param id - The request ID to respond to
   303→   * @param result - The result to send back
   304→   */
   305→  respond(id: string | number, result: unknown): void {
   306→    this.framing.sendResponse(id, result);
   307→  }
   308→
   309→  /**
   310→   * Send a typed response to a permission request
   311→   *
   312→   * @param id - The request ID to respond to
   313→   * @param response - The permission response
   314→   */
   315→  respondPermission(
   316→    id: string | number,
   317→    response: RequestPermissionResponse,
   318→  ): void {
   319→    this.framing.sendResponse(id, response);
   320→  }
   321→
   322→  /**
   323→   * Send an error response to an agent request
   324→   *
   325→   * @param id - The request ID to respond to
   326→   * @param code - Error code
   327→   * @param message - Error message
   328→   */
   329→  respondError(id: string | number, code: number, message: string): void {
   330→    this.framing.sendError(id, { code, message });
   331→  }
   332→
   333→  /**
   334→   * Close the client connection
   335→   *
   336→   * Rejects any pending requests and cleans up resources.
   337→   */
   338→  close(): void {
   339→    this.framing.close();
   340→  }
   341→
   342→  /**
   343→   * Handle incoming notifications from the agent
   344→   */
   345→  private handleNotification(notification: JsonRpcNotification): void {
   346→    if (notification.method === "session/update") {
   347→      const sessionNotification = notification.params as SessionNotification;
   348→      this.emit(
   349→        "update",
   350→        sessionNotification.sessionId,
   351→        sessionNotification.update,
   352→      );
   353→    }
   354→  }
   355→}
