      });

      client.respond(id, result);
      break;
    }

    default:
      // Unknown method - return error
      client.respondError(id, -32601, `Method not found: ${method}`);
  }
} catch (err) {
  const message = err instanceof Error ? err.message : String(err);
  client.respondError(id, -32000, message);
}

