/**
 * ACP (Agent Communication Protocol) Type Definitions
 *
 * This module re-exports types from the official @agentclientprotocol/sdk
 * to ensure spec compliance. Types are imported at compile-time only
 * (zero runtime cost since TypeScript types are erased).
 *
 * We keep JSON-RPC 2.0 base types and type guards local since the SDK
 * doesn't export them in the same way we use them.
 */

// ============================================================================
// ACP Types from Official SDK
//
// Import relevant types from the SDK. These are guaranteed to match the
// official ACP specification.
// ============================================================================

export type {
  AgentCapabilities,
  ClientCapabilities,
  ContentBlock,
  CreateTerminalRequest,
  CreateTerminalResponse,
  InitializeRequest,
  InitializeResponse,
  NewSessionRequest,
  NewSessionResponse,
  PromptRequest,
  PromptResponse,
  ReadTextFileRequest,
  ReadTextFileResponse,
  RequestPermissionRequest,
  RequestPermissionResponse,
  SessionNotification,
  SessionUpdate,
  StopReason,
  TerminalOutputRequest,
  TerminalOutputResponse,
  TextContent,
  WriteTextFileRequest,
  WriteTextFileResponse,
} from "@agentclientprotocol/sdk";

// ============================================================================
// JSON-RPC 2.0 Base Types
//
// These are kept local because:
// 1. The SDK's internal JSON-RPC types aren't exported the same way
// 2. We need specific shapes for our type guards
// 3. These are standard JSON-RPC types, not ACP-specific
// ============================================================================

/**
 * JSON-RPC 2.0 Request
 */
export interface JsonRpcRequest {
  jsonrpc: "2.0";
  id: string | number;
  method: string;
  params?: unknown;
}

/**
 * JSON-RPC 2.0 Response (success)
 */
export interface JsonRpcResponse {
  jsonrpc: "2.0";
  id: string | number;
  result: unknown;
}

/**
 * JSON-RPC 2.0 Error object
 */
export interface JsonRpcErrorObject {
  code: number;
  message: string;
  data?: unknown;
}

/**
 * JSON-RPC 2.0 Error response
 */
export interface JsonRpcError {
  jsonrpc: "2.0";
  id: string | number | null;
  error: JsonRpcErrorObject;
}

/**
 * JSON-RPC 2.0 Notification (no response expected)
 */
export interface JsonRpcNotification {
  jsonrpc: "2.0";
  method: string;
  params?: unknown;
}

/**
 * Any JSON-RPC message type
 */
export type JsonRpcMessage =
  | JsonRpcRequest
  | JsonRpcResponse
  | JsonRpcError
  | JsonRpcNotification;

// ============================================================================
// Validation Helpers
//
// Simple runtime type checks used by the JSON-RPC type guards.
// ============================================================================

/**
 * Check if a value is a non-null object
 */
export function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/**
 * Check if a value is a string
 */
export function isString(value: unknown): value is string {
  return typeof value === "string";
}

/**
 * Check if a value is a number
 */
export function isNumber(value: unknown): value is number {
  return typeof value === "number" && !Number.isNaN(value);
}

/**
 * Check if an object has a specific property with an optional specific value
 */
export function hasProperty<T extends string>(
  obj: unknown,
  key: T,
  value?: unknown,
): obj is Record<T, unknown> {
  if (!isObject(obj)) return false;
  if (!(key in obj)) return false;
  if (value !== undefined && obj[key] !== value) return false;
  return true;
}

// ============================================================================
// JSON-RPC Type Guards
//
// Runtime type guards for validating incoming messages.
// These work with unknown data and narrow to specific types.
// ============================================================================

/**
 * Type guard for JSON-RPC Request
 */
export function isRequest(msg: unknown): msg is JsonRpcRequest {
  return (
    isObject(msg) &&
    hasProperty(msg, "jsonrpc", "2.0") &&
    "id" in msg &&
    (isString(msg.id) || isNumber(msg.id)) &&
    hasProperty(msg, "method") &&
    isString(msg.method)
  );
}

/**
 * Type guard for JSON-RPC Response
 */
export function isResponse(msg: unknown): msg is JsonRpcResponse {
  return (
    isObject(msg) &&
    hasProperty(msg, "jsonrpc", "2.0") &&
    "id" in msg &&
    (isString(msg.id) || isNumber(msg.id)) &&
    "result" in msg &&
    !("error" in msg)
  );
}

/**
 * Type guard for JSON-RPC Error
 */
export function isError(msg: unknown): msg is JsonRpcError {
  return (
    isObject(msg) &&
    hasProperty(msg, "jsonrpc", "2.0") &&
    "id" in msg &&
    (msg.id === null || isString(msg.id) || isNumber(msg.id)) &&
    hasProperty(msg, "error") &&
    isObject(msg.error) &&
    hasProperty(msg.error, "code") &&
    isNumber(msg.error.code) &&
    hasProperty(msg.error, "message") &&
    isString(msg.error.message)
  );
}

/**
 * Type guard for JSON-RPC Notification
 */
export function isNotification(msg: unknown): msg is JsonRpcNotification {
  return (
    isObject(msg) &&
    hasProperty(msg, "jsonrpc", "2.0") &&
    !("id" in msg) &&
    hasProperty(msg, "method") &&
    isString(msg.method)
  );
}

/**
 * ACP (Agent Communication Protocol) Module
 *
 * Provides a JSON-RPC 2.0 based client for Agent Client Protocol communication.
 * Handles bidirectional stdio communication with ACP-compliant agents.
 */

export type {
  ACPClientEvents,
  ACPClientOptions,
  SessionState,
} from "./client.js";
// Client
export { ACPClient } from "./client.js";
export type {
  JsonRpcFramingOptions,
  SendRequestOptions,
} from "./framing.js";
// Framing layer
export { JsonRpcFraming } from "./framing.js";
// Types - JSON-RPC
// Types - ACP (re-exported from SDK)
export type {
  AgentCapabilities,
  ClientCapabilities,
  ContentBlock,
  CreateTerminalRequest,
  CreateTerminalResponse,
  InitializeRequest,
  InitializeResponse,
  JsonRpcError,
  JsonRpcErrorObject,
  JsonRpcMessage,
  JsonRpcNotification,
  JsonRpcRequest,
  JsonRpcResponse,
  NewSessionRequest,
  NewSessionResponse,
  PromptRequest,
  PromptResponse,
  ReadTextFileRequest,
  ReadTextFileResponse,
  RequestPermissionRequest,
  RequestPermissionResponse,
  SessionNotification,
  SessionUpdate,
  StopReason,
  TerminalOutputRequest,
  TerminalOutputResponse,
  TextContent,
  WriteTextFileRequest,
  WriteTextFileResponse,
} from "./types.js";
// Types - Type guards
export {
  isError,
  isNotification,
  isRequest,
  isResponse,
} from "./types.js";

import chalk from "chalk";
import type { Command } from "commander";
import { buildIndexes, initContext } from "../../parser/index.js";
import type { LoadedSpecItem, LoadedTask } from "../../parser/yaml.js";
import { errors } from "../../strings/index.js";
import { formatMatchedFields, grepItem } from "../../utils/grep.js";
import { EXIT_CODES } from "../exit-codes.js";
import { error, output } from "../output.js";

/**
 * Format a spec item for search results
 */
function formatSearchItem(item: LoadedSpecItem, matchedFields: string[]): void {
  const shortId = item._ulid.slice(0, 8);
  const slugStr = item.slugs.length > 0 ? chalk.cyan(`@${item.slugs[0]}`) : "";
  const typeStr = chalk.gray(`[${item.type}]`);

  let status = "";
  if (item.status && typeof item.status === "object") {
    const s = item.status as { maturity?: string; implementation?: string };
    if (s.implementation) {
      const implColor =
        s.implementation === "verified"
          ? chalk.green
          : s.implementation === "implemented"
            ? chalk.cyan
            : s.implementation === "in_progress"
              ? chalk.yellow
              : chalk.gray;
      status = implColor(s.implementation);
    }
  }

  let line = `${chalk.gray(shortId)} ${typeStr} ${item.title}`;
  if (slugStr) line += ` ${slugStr}`;
  if (status) line += ` ${status}`;

  console.log(line);
  console.log(chalk.gray(`  matched: ${formatMatchedFields(matchedFields)}`));
}

/**
 * Format a task for search results
 */
function formatSearchTask(task: LoadedTask, matchedFields: string[]): void {
  const shortId = task._ulid.slice(0, 8);
  const slugStr = task.slugs.length > 0 ? chalk.cyan(`@${task.slugs[0]}`) : "";

  const statusColor =
    task.status === "completed"
      ? chalk.green
      : task.status === "in_progress"
        ? chalk.blue
        : task.status === "blocked"
          ? chalk.red
          : chalk.gray;

  const priority =
    task.priority <= 2
      ? chalk.red(`P${task.priority}`)
      : chalk.gray(`P${task.priority}`);

  let line = `${chalk.gray(shortId)} ${statusColor(`[${task.status}]`)} ${priority} ${task.title}`;
  if (slugStr) line += ` ${slugStr}`;

  console.log(line);
  console.log(chalk.gray(`  matched: ${formatMatchedFields(matchedFields)}`));
}

interface SearchResult {
  type: "item" | "task";
  item: LoadedSpecItem | LoadedTask;
  matchedFields: string[];
}

/**
 * Register the search command
 */
export function registerSearchCommand(program: Command): void {
  program
    .command("search <pattern>")
    .description("Search across all items and tasks with regex pattern")
    .option("-t, --type <type>", "Filter by item type")
    .option("-s, --status <status>", "Filter by task status")
    .option("--items-only", "Search only spec items")
    .option("--tasks-only", "Search only tasks")
    .option("--limit <n>", "Limit results", "50")
    .action(async (pattern, options) => {
      try {
        const ctx = await initContext();
        const { itemIndex, tasks, items, refIndex } = await buildIndexes(ctx);

        const results: SearchResult[] = [];
        const limit = parseInt(options.limit, 10) || 50;

        // Search spec items
        if (!options.tasksOnly) {
          for (const item of items) {
            // Apply type filter
            if (options.type && item.type !== options.type) continue;

            const match = grepItem(
              item as unknown as Record<string, unknown>,
              pattern,
            );
            if (match) {
              results.push({
                type: "item",
                item,
                matchedFields: match.matchedFields,
              });
            }
          }
        }

        // Search tasks
        if (!options.itemsOnly) {
          for (const task of tasks) {
            // Apply status filter
            if (options.status && task.status !== options.status) continue;

            const match = grepItem(
              task as unknown as Record<string, unknown>,
              pattern,
            );
            if (match) {
              results.push({
                type: "task",
                item: task,
                matchedFields: match.matchedFields,
              });
            }
          }
        }

        // Limit results
        const limitedResults = results.slice(0, limit);

        output(
          {
            pattern,
            results: limitedResults.map((r) => ({
              type: r.type,
              ulid: r.item._ulid,
              title: r.item.title,
              matchedFields: r.matchedFields,
            })),
            total: results.length,
            showing: limitedResults.length,
          },
          () => {
            if (limitedResults.length === 0) {
              console.log(chalk.gray(`No matches found for "${pattern}"`));
              return;
            }

            for (const result of limitedResults) {
              if (result.type === "item") {
                formatSearchItem(
                  result.item as LoadedSpecItem,
                  result.matchedFields,
                );
              } else {
                formatSearchTask(
                  result.item as LoadedTask,
                  result.matchedFields,
                );
              }
            }

            console.log(
              chalk.gray(
                `\n${limitedResults.length} result(s)${results.length > limit ? ` (showing first ${limit})` : ""}`,
              ),
            );
          },
        );
      } catch (err) {
        error(errors.failures.search, err);
        process.exit(EXIT_CODES.ERROR);
      }
    });
}

